  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is humanoid robot data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of demonstrations that teach humanoids to move, balance, and manipulate objects, combining teleoperation on the real robot, egocentric human video with motion tracking, retargeted motion, and simulation."
        }
      },
      {
        "@type": "Question",
        "name": "How do you teleoperate a humanoid for data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We use VR, 3D mouse, leader-arm, and exoskeleton-style interfaces depending on the task, recording the robot's own joint states, cameras, and actions. On the Feather program we run both 3D mouse and VR input on the real robot."
        }
      },
      {
        "@type": "Question",
        "name": "Is human video useful for training humanoids?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, for pretraining and task breadth, if hand and body poses can be mapped onto your robot. We validate retargeting on a sample before scaling egocentric capture."
        }
      },
      {
        "@type": "Question",
        "name": "Which models has your humanoid data trained?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Data from our Feather Robotics program has been used to post-train SmolVLA and π0.5 models."
        }
      },
      {
        "@type": "Question",
        "name": "How do you capture whole-body and balance data safely?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Tasks that shift the robot's center of mass are recorded with the base active, under safety gantries or spotters, with stumbles and recoveries tagged for training and evaluation."
        }
      },
      {
        "@type": "Question",
        "name": "Can you build evaluation suites for humanoid policies?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We hold out tasks, scenes, and edge cases from training and turn them into repeatable evaluation suites through our validation and testing service."
        }
      }
    ]
  }
